// Command Composal-cli is a CLI + REPL for the Composal SDK,
// built on the boru engine. Positional arguments are joined into a
// single boru expression and evaluated; with no arguments, falls into
// a REPL. Generated by sdkgen go-cli target.
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"

	eng "github.com/boru-lang/boru/eng/go"
	"github.com/boru-lang/boru/eng/go/parser"
	sdk "github.com/voxgig-sdk/composal-sdk/go"
)

// prompt is the REPL prompt prefix (matches the SDK slug).
const prompt = "composal"

// entitiesHelp is the space-separated entity list shown by /help.
const entitiesHelp = "agent agent_attachment agent_automation agent_avatar agent_command agent_computer agent_connection agent_control_flow agent_coordination agent_email agent_file agent_input agent_integration agent_interaction agent_library agent_manager agent_manager_choice agent_marketplace agent_marketplace_shared agent_mission_control agent_operation agent_provisioning agent_pull_request agent_question agent_repository agent_resource agent_routine agent_run agent_runtime agent_setting agent_sharing agent_site agent_skill agent_slack agent_subagent agent_subscription agent_teammate agent_terminal agent_thread agent_tool agent_verify_project agent_wait agent_webhook agent_work agent_workflow agent_workflow_proposal agent_workflow_run agent_workflow_trigger agent_workspace agent_write_permission allocation_log app app_cdn app_config_variable app_data_resource app_deploy app_deployment app_deployment_operation app_deployment_rollback app_environment app_location app_metric app_preview app_preview_profile app_run app_secret app_service app_service_binding app_service_placement app_storage_resource attachment_part automation_event automation_run binary binary_version browser_egress_candidate browser_session browser_session_connection browser_session_control browser_session_event browser_session_media browser_session_recording browser_session_screenshot browser_session_task catalog_selector cdn_deployment cdn_hostname cdn_space cdn_space_object connection_request connection_source coordination_wait credential_sign_in_check data_resource_rotate_credential deep_scan deep_scan_finding deep_scan_flow deep_scan_mapped_flow deep_scan_option demo_share demo_share_segment deployment_dashboard_nomad deployment_file domain_path_rule dream environment environment_discovery_run environment_exploration environment_first_run environment_revision environment_secret_binding environment_test_account evidence exploration exploration_message exploration_report exploration_scenario finding github_connection hosting_app_domain image_repository integration interaction_response invitation journey_variant_replay knowledge local_thread_delivery local_thread_operation location me me_email me_onboarding media_file member memory merge_request messaging_conversation_message messaging_conversation_upload metric_query network_connection nomad_allocation nomad_log organization page page_agent page_project_run pages_project_credential pages_project_persona pages_project_run pages_project_scenario personal_access_token preview_operation preview_profile_secret_binding preview_secret preview_sharing_approval product_map_identity_decision product_map_journey product_map_journey_replay product_map_observation product_map_question product_map_state project project_android_apk project_code_map project_environment project_finding project_fixture project_ios_app project_messaging_conversation project_overview_metric project_overview_pull_request project_product_map project_recording project_run_plan project_run_schedule project_scenario_option project_scenario_row project_setting pull_request pull_request_setting pull_request_setting_add_repository pull_request_setting_detect_comment recorder registry registry_v2 relay_agent_local_thread report_replay report_scenario run_scenario_run run_schedule_option run_search run_update scenario_revision scenario_run_lesson scenario_run_scenario_edit service_endpoint site_preview slack_channel spark_agent_local_thread static_site static_site_deployment static_site_domain subscription_model thread_preview verification_project_credential verification_project_persona verification_project_run verification_project_scenario verify_app_domain verify_browser_session verify_static_site_domain version_log web_bot_auth workflow_run_step workflow_run_stop_notice workflow_trigger_skipped"

func main() {
	os.Exit(run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

// usage prints the CLI help (for --help / -h). No client or network setup.
func usage(out io.Writer) {
	fmt.Fprintf(out, "%s-cli — boru-driven CLI + REPL for the %s SDK\n\n", prompt, prompt)
	fmt.Fprintln(out, "Usage:")
	fmt.Fprintf(out, "  %s-cli [--help] [<boru expression>]\n\n", prompt)
	fmt.Fprintln(out, "With arguments, they are joined into a single boru expression and")
	fmt.Fprintln(out, "evaluated against the API. With no arguments, starts an interactive REPL.")
	fmt.Fprintln(out)
	fmt.Fprintln(out, "Words:    list / load / update <query?> <entity>")
	fmt.Fprintln(out, "Entities:", entitiesHelp)
	fmt.Fprintln(out, "Env:      COMPOSAL_APIKEY (api key), COMPOSAL_BASE (base url override)")
	fmt.Fprintln(out, "REPL:     /help  /quit")
}

func run(args []string, in io.Reader, out, errOut io.Writer) int {
	// --help / -h: print usage and exit before any config or network setup.
	for _, a := range args {
		if a == "--help" || a == "-h" {
			usage(out)
			return 0
		}
	}

	// Configure from the environment: COMPOSAL_APIKEY carries the API key and
	// COMPOSAL_BASE optionally overrides the API base URL (e.g. production).
	// Both injectable by a secrets vault. Unset -> nil config defaults.
	var opts map[string]any
	if apikey := os.Getenv("COMPOSAL_APIKEY"); apikey != "" {
		opts = map[string]any{"apikey": apikey}
	}
	if base := os.Getenv("COMPOSAL_BASE"); base != "" {
		if opts == nil {
			opts = map[string]any{}
		}
		opts["base"] = base
	}
	client := sdk.NewComposalSDK(opts)

	r, err := eng.NewRegistry()
	if err != nil {
		fmt.Fprintf(errOut, "registry: %v\n", err)
		return 1
	}
	registerSDKWords(r, client)
	if err := r.Err(); err != nil {
		fmt.Fprintf(errOut, "word registration: %v\n", err)
		return 1
	}
	r.SetParseFunc(parser.Parse)
	r.InitRootContext()
	r.MarkReady()

	if len(args) > 0 {
		return evalOnce(r, strings.Join(args, " "), out, errOut)
	}
	repl(r, in, out)
	return 0
}

func evalOnce(r *eng.Registry, src string, out, errOut io.Writer) int {
	values, err := parser.Parse(src)
	if err != nil {
		fmt.Fprintf(errOut, "parse: %v\n", err)
		return 1
	}
	result, err := eng.NewTop(r).Run(values)
	if err != nil {
		fmt.Fprintf(errOut, "error: %v\n", err)
		return 1
	}
	for _, v := range result {
		fmt.Fprintln(out, v.String())
	}
	return 0
}

func repl(r *eng.Registry, in io.Reader, out io.Writer) {
	scanner := bufio.NewScanner(in)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	for {
		fmt.Fprintf(out, "%s> ", prompt)
		if !scanner.Scan() {
			fmt.Fprintln(out)
			return
		}
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		switch line {
		case "/quit", "/q", "/exit":
			return
		case "/help", "/h", "/?":
			fmt.Fprintln(out, "words:    list / load / update <query?> <entity>")
			fmt.Fprintln(out, "entities:", entitiesHelp)
			fmt.Fprintln(out, "meta:     /help  /quit")
			continue
		}
		values, err := parser.Parse(line)
		if err != nil {
			fmt.Fprintf(out, "  parse error: %v\n", err)
			continue
		}
		result, err := eng.NewTop(r).Run(values)
		if err != nil {
			fmt.Fprintf(out, "  error: %v\n", err)
			continue
		}
		for _, v := range result {
			fmt.Fprintln(out, v.String())
		}
	}
}
